package __PKG__;

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;

/** A position in a world. Generated by Minecraft Builder. */
public record Loc(ServerLevel level, double x, double y, double z) {
    public static Loc of(Entity e) {
        return new Loc((ServerLevel) e.level(), e.getX(), e.getY(), e.getZ());
    }

    public Loc add(double dx, double dy, double dz) {
        return new Loc(level, x + dx, y + dy, z + dz);
    }
}
